import { BEAR_HEAD, BEAR_HEAD_COLOURS } from '../ar/framed.ts';
import { DESK, PRINT_SHEET } from '../content/intro.ts';
import { h } from './dom.ts';

/**
 * The two codes: a QR code inside the frame the AR page looks for. A phone
 * camera reads the QR and opens the AR page, and that page recognises the
 * frame around it. Generated by tools/make-framed-marker.ts.
 */
const PAPER_CODE = `${import.meta.env.BASE_URL}ar/pal-marker.png`; // pink, for paper
const SCREEN_CODE = `${import.meta.env.BASE_URL}ar/pal-marker-screen.png`; // blue, for a screen

function code(src: string, className: string): HTMLImageElement {
  const img = h('img', { class: className, attrs: { src, alt: PRINT_SHEET.codeAlt } });
  // A missing file should leave a gap, not a broken-image icon.
  img.addEventListener('error', () => {
    img.hidden = true;
  });
  return img;
}

/** The surprise on a computer screen: the blue code, as big as its box allows. */
export function surprise(): HTMLElement {
  return h('figure', { class: 'surprise' }, code(SCREEN_CODE, 'surprise__code'));
}

/**
 * Opens the browser's own print dialog with nothing but the pink code on the
 * page. The dialog is the real one, and a page cannot tell whether it ended in
 * "Print" or "Cancel": `onClosed` only means the dialog is gone.
 */
export function printSurprise(onClosed: () => void): void {
  const img = code(PAPER_CODE, 'print-sheet__code');
  const sheet = h('div', { class: 'print-sheet', attrs: { 'aria-hidden': 'true' } }, img);
  document.body.append(sheet);

  // Signs that the player is back on the page: the dialog is modal, so none of these come while it is open.
  const BACK = ['pointermove', 'pointerdown', 'keydown'] as const;
  let closed = false;
  const finish = (): void => {
    if (closed) return;
    closed = true;
    window.removeEventListener('afterprint', finish);
    for (const type of BACK) window.removeEventListener(type, finish);
    sheet.remove();
    onClosed();
  };
  const open = (): void => {
    if (closed) return;
    window.addEventListener('afterprint', finish);
    try {
      window.print();
    } catch {
      // No printing here at all: carry on as if the dialog had been closed.
    }
    // Where `print()` returns at once and `afterprint` never comes, the first
    // sign of the player being back ends the wait. The sheet stays until then,
    // so a dialog that is still open never gets an empty page.
    if (!closed) window.setTimeout(() => !closed && BACK.forEach((type) => window.addEventListener(type, finish)), 400);
  };
  // The picture has to be there before the page is handed to the printer.
  if (img.complete) open();
  else {
    const ready = (): void => {
      window.clearTimeout(patience);
      open();
    };
    const patience = window.setTimeout(open, 2500);
    img.addEventListener('load', ready, { once: true });
    img.addEventListener('error', ready, { once: true });
  }
}

/** The bear's head as a little pixel picture: the dialog's icon, and the whole surprise on a phone. */
export function bearCanvas(className: string, label?: string): HTMLCanvasElement {
  const size = BEAR_HEAD.length;
  const canvas = h('canvas', {
    class: className,
    attrs: label ? { width: String(size), height: String(size), role: 'img', 'aria-label': label } : { width: String(size), height: String(size), 'aria-hidden': 'true' },
  });
  const g = canvas.getContext('2d');
  if (g) {
    BEAR_HEAD.forEach((row, y) => {
      [...row].forEach((char, x) => {
        const rgb = BEAR_HEAD_COLOURS[char];
        if (!rgb) return;
        g.fillStyle = `rgb(${rgb[0]}, ${rgb[1]}, ${rgb[2]})`;
        g.fillRect(x, y, 1, 1);
      });
    });
  }
  return canvas;
}

/** The surprise on a phone, where there is no printer and no second screen to point a camera at: the bear's picture. */
export function bearPicture(): HTMLElement {
  return h('figure', { class: 'surprise' }, bearCanvas('surprise__bear', DESK.picture.alt));
}
